const assets={"/":["text/html; charset=utf-8","<!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Xarun Market</title><style>\r\n*{box-sizing:border-box}body{--bg:#faf9f4;--ink:#153c32;--card:white;background:var(--bg);color:var(--ink);font:16px system-ui;margin:0}body.dark{--bg:#142720;--ink:#f0f4ed;--card:#223c31}header,main,footer{max-width:1250px;margin:auto;padding:20px 5%}header{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}strong{font:bold 27px Georgia}button,input,select{font:inherit;border:1px solid #80988a;border-radius:8px;padding:9px 12px;background:var(--card);color:var(--ink)}button{cursor:pointer}button:hover{border-color:#498362}.hero{background:#17483b;color:white;padding:clamp(24px,5vw,65px);border-radius:22px;position:relative;overflow:hidden}.hero:after{content:'✺';position:absolute;right:-3%;top:-55%;font:450px Georgia;color:#37725e;pointer-events:none}.hero>*{position:relative;z-index:1}h1{font:clamp(44px,7vw,81px)/1 Georgia;margin:14px 0}.hero button,.buy{background:#e4efac;color:#163e31;border:0;font-weight:650}h2{font:36px Georgia;margin:28px 0 15px}.tools,nav{display:flex;gap:7px;flex-wrap:wrap}.tools input{flex:1;min-width:150px}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(210px,100%),1fr));gap:16px;margin-top:20px}.tile{text-align:left;background:var(--card);padding:0;border:0;overflow:hidden;border-radius:12px;box-shadow:0 1px 4px #173d3220}.tile span{display:block;padding:4px 16px}.tile b{display:block;padding:0 16px 15px}.photo{width:100%;height:210px;object-fit:cover;background:#e7e3d6}.tile small{display:block;padding:12px 16px 0;color:#59816e}.tile span{font:bold 21px Georgia}dialog{background:var(--bg);color:var(--ink);width:min(520px,94vw);max-height:85vh;border:0;border-radius:16px;padding:24px}dialog::backdrop{background:#102b2380}.close{float:right}label{display:grid;gap:4px;margin:10px 0}.row{border-bottom:1px solid #aab9af;padding:12px 0}footer{display:flex;justify-content:space-between;align-items:center}.hero p{max-width:420px}.active{background:#225640;color:white}\r\n</style><link rel=\"stylesheet\" href=\"/style.css\"><link rel=\"stylesheet\" href=\"/chatbot.css\"><body class=\"store\"><header><a class=\"brand\" href=\"/\">Xarun<span>Market</span></a><nav aria-label=\"Departments\"><a href=\"#shop\" onclick=\"browse('All')\">Shop all</a><a href=\"#shop\" onclick=\"browse('Fashion')\">Fashion</a><a href=\"#shop\" onclick=\"browse('Electronics')\">Electronics</a><a href=\"#shop\" onclick=\"browse('Food')\">Pantry</a></nav><div class=\"utility\"><a class=\"accountlink\" href=\"/account\">My account</a><button id=\"saved\">♡ Saved</button><button id=\"theme\" aria-label=\"Switch color theme\">◐</button><button id=\"bag\"></button></div></header>\r\n<main><section class=\"cover\"><div><small>XARUN MARKET / SOMALIA</small><h1>Everyday<br><em>essentials.</em></h1><p>From cotton tees to basmati rice, find your everyday favourites in one place.</p><a class=\"cta\" href=\"#shop\" onclick=\"browse('All')\">Shop all products →</a></div><figure><img src=\"https://images.unsplash.com/photo-1542838132-92c53300491e?w=1050&q=85\" alt=\"A colourful display of fresh market produce\"><figcaption><span>The pantry collection</span><a href=\"#shop\" onclick=\"browse('Food')\" aria-label=\"Shop the pantry collection\">↗</a></figcaption></figure></section>\r\n<section aria-labelledby=\"shop\"><h2 id=\"shop\">Explore the market</h2><div class=\"tools\"><input id=\"search\" placeholder=\"Search the market…\" aria-label=\"Search products\"><select id=\"sort\" aria-label=\"Sort products\"><option>Featured</option><option>Price: low to high</option><option>Price: high to low</option></select></div><p id=\"filters\"></p><section class=\"grid\" id=\"products\"></section></section></main>\r\n<footer class=\"shopfoot\"><div><a class=\"brand\" href=\"/\">Xarun<span>Market</span></a><p>Fashion, electronics and pantry staples.</p></div><div><b>Departments</b><a href=\"#shop\" onclick=\"browse('Fashion')\">Fashion</a><a href=\"#shop\" onclick=\"browse('Electronics')\">Electronics</a><a href=\"#shop\" onclick=\"browse('Food')\">Pantry</a></div><div><b>Customer care</b><a href=\"/account\">My orders</a><button id=\"track\">Track an order</button><button id=\"help\">Shopping assistant</button><button onclick=\"document.getElementById('saved').click()\">Saved products</button></div><div><b>Store</b><small>Prices in USD<br>Demo checkout</small></div></footer><dialog id=\"modal\"><button class=\"close\" onclick=\"modal.close()\">Close</button><article id=\"panel\"></article></dialog><script src=\"shop.js\"></script><script type=\"module\" src=\"/chatbot.js\"></script></html>\r\n\r\n\r\n"],"/admin":["text/html; charset=utf-8","<!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Store administration · Xarun Market</title><link rel=\"stylesheet\" href=\"/style.css\"><body class=\"desk\"><aside><a class=\"brand\" href=\"/\">Xarun<span>Market</span></a><small>STORE MANAGEMENT</small><nav aria-label=\"Administration\"><a href=\"/admin\">Dashboard</a><a class=\"signed\" href=\"#orderlist\">Orders</a><a href=\"#access\">Sign-in guide</a></nav><a class=\"back\" href=\"/\">← View storefront</a></aside><div class=\"deskpage\"><header><b>Store administration</b><a href=\"/\">Storefront ↗</a></header><main><h1 id=\"heading\">Admin sign-in</h1><section class=\"console\"><p id=\"message\" role=\"status\">Checking access…</p><section id=\"workspace\"></section></section><details id=\"access\"><summary>How to sign in as admin</summary><ol><li>Enter the admin email and password configured by the store owner.</li><li>Select <b>Sign in as admin</b> to manage orders.</li></ol></details></main><footer>Xarun Market · Store administration <a href=\"/\">Return to shop ↗</a></footer></div><script src=\"/admin.js\"></script></body></html>\r\n"],"/account":["text/html; charset=utf-8","<!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>My account · Xarun Market</title><link rel=\"stylesheet\" href=\"/style.css\"><body class=\"desk customer\"><header><a class=\"brand\" href=\"/\">Xarun<span>Market</span></a><nav><a href=\"/\">Shop the market</a><a id=\"signout\" hidden href=\"#\">Sign out</a></nav></header><main><small>YOUR ACCOUNT</small><h1>My account</h1><p>Sign in to access your Xarun Market account.</p><p id=\"feedback\" role=\"status\">Loading your account…</p><section id=\"history\"></section></main><footer>Xarun Market<a href=\"/\">Continue shopping →</a></footer><script src=\"/account.js\"></script></body></html>\r\n"],"/account.js":["text/javascript; charset=utf-8","const historyPanel=document.querySelector('#history'),feedback=document.querySelector('#feedback');\r\nconst escapeText=value=>String(value).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\r\nasync function loadHistory(){\r\n feedback.textContent='Loading your orders…';\r\n try{\r\n  const stateResponse=await fetch('/api/account');\r\n  if(!stateResponse.ok)throw Error('Unable to check your account. Please try again.');\r\n  const state=await stateResponse.json();\r\n  if(state.role==='admin'){location.replace('/admin');return}\r\n  const response=await fetch('/api/account/orders');\r\n  if(response.status===401){\r\n   feedback.textContent='';\r\n   renderLogin();\r\n   return;\r\n  }\r\n  if(!response.ok)throw Error('Your order history is unavailable. Please try again.');\r\n  const orders=await response.json();\r\n  document.querySelector('#signout').hidden=false;\r\n  feedback.textContent='';\r\n  historyPanel.innerHTML='<button id=\"reload\">Refresh status</button>'+orders.map(order=>{\r\n   const stages=['Received','Packing','Shipped','Delivered'];\r\n   return '<article class=\"ordercard\"><div class=\"orderheading\"><b>'+escapeText(order.id)+'</b><span class=\"badge '+escapeText(order.status)+'\">'+escapeText(order.status)+'</span></div><small>'+escapeText(order.created)+' UTC</small><ol class=\"progress\">'+(order.status==='Cancelled'?'<li>Order cancelled</li>':stages.map((s,i)=>'<li class=\"'+(i<=stages.indexOf(order.status)?'reached':'')+'\">'+s+'</li>').join(''))+'</ol><ul>'+JSON.parse(order.items).map(item=>'<li>'+escapeText(item.name)+' × '+item.qty+' <b>$'+(item.price*item.qty).toFixed(2)+'</b></li>').join('')+'</ul><p>Total <b>$'+order.total.toFixed(2)+'</b> · '+escapeText(order.method)+'</p></article>';\r\n  }).join('')+(orders.length?'':'<section class=\"console\"><h2>Your next find is waiting</h2><p>Your purchases will appear here after checkout.</p><a class=\"primary\" href=\"/\">Explore the market →</a></section>');\r\n  document.querySelector('#reload').onclick=loadHistory;\r\n }catch(error){feedback.textContent=error.message;historyPanel.innerHTML='<button id=\"retry\">Try again</button>';document.querySelector('#retry').onclick=loadHistory}\r\n}\r\nlet actionToken;\r\nlet actionMode;\r\nfunction renderLogin(mode='login'){\r\n document.querySelector('#signout').hidden=true;\r\n const needsPassword=['login','verify','reset'].includes(mode);\r\n const titles={login:'Welcome back',signup:'Create your account',resend:'Resend verification email',forgot:'Reset your password',verify:'Verify your email',reset:'Choose a new password'};\r\n historyPanel.innerHTML='<section class=\"console\"><h2>'+titles[mode]+'</h2><p>'+(['verify','reset'].includes(mode)?'Choose a password of at least 12 characters for Xarun Market.':'Enter your email address to continue.')+'</p><form id=\"customer-login\">'+(!['verify','reset'].includes(mode)?'<label>Email address<input type=\"email\" name=\"email\" required autocomplete=\"username\" placeholder=\"you@gmail.com\"></label>':'')+(needsPassword?'<label>Password<input type=\"password\" name=\"password\" required minlength=\"12\" maxlength=\"128\" autocomplete=\"'+(mode==='login'?'current-password':'new-password')+'\"></label>':'')+'<button>'+({login:'Sign in',signup:'Send verification email',resend:'Send verification email',forgot:'Send reset link',verify:'Verify email and save password',reset:'Save new password'}[mode])+'</button></form><div class=\"authlinks\"><button data-mode=\"login\">Sign in</button><button data-mode=\"signup\">Create account</button><button data-mode=\"forgot\">Forgot password?</button><button data-mode=\"resend\">Resend verification email</button></div></section>';\r\n historyPanel.querySelectorAll('[data-mode]').forEach(button=>button.onclick=()=>{feedback.textContent='';renderLogin(button.dataset.mode)});\r\n document.querySelector('#customer-login').onsubmit=async event=>{\r\n  event.preventDefault();\r\n  const form=event.target,button=form.querySelector('button');button.disabled=true;feedback.textContent='';\r\n  try{\r\n   const payload={email:form.elements.email?.value,password:form.elements.password?.value,token:actionToken};\r\n   const response=await fetch('/api/auth/'+mode,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});\r\n   const result=await response.json();if(!response.ok)throw Error(result.error);\r\n   if(mode!=='login'){renderLogin('login');feedback.textContent=result.message;return}\r\n   if(result.role==='admin'){location.replace('/admin');return}\r\n   if(new URLSearchParams(location.search).get('return')==='checkout'){location.href='/#shop';return}\r\n   await loadHistory();\r\n  }catch(error){feedback.textContent=error.message;button.disabled=false}\r\n };\r\n}\r\ndocument.querySelector('#signout').onclick=async event=>{\r\n event.preventDefault();\r\n try{\r\n  const response=await fetch('/api/auth/logout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});\r\n  if(!response.ok)throw Error('Unable to sign out. Try again.');\r\n  historyPanel.replaceChildren();await loadHistory();\r\n }catch(error){feedback.textContent=error.message}\r\n};\r\nfunction openAccountPage(){\r\n const params=new URLSearchParams(location.hash.slice(1));\r\n actionToken=params.get('token');actionMode=params.get('action');\r\n if(actionToken)history.replaceState(null,'',location.pathname+location.search);\r\n if(actionToken&&['verify','reset'].includes(actionMode)){feedback.textContent='';renderLogin(actionMode)}\r\n else loadHistory();\r\n}\r\nwindow.addEventListener('hashchange',openAccountPage);\r\nopenAccountPage();\r\n"],"/shop.js":["text/javascript; charset=utf-8","const data=[[\"Cotton everyday tee\",14,\"Soft cotton with an easy, relaxed fit.\",\"tops\",\"tshirt\",\"/products/0.image\"],[\"Canvas tote\",18,\"A roomy carryall for market days.\",\"womens-bags\",\"blue-womens-handbag\",\"/products/1.image\"],[\"Classic watch\",36,\"A simple everyday timepiece.\",\"mens-watches\",\"brown-leather-belt-watch\",\"/products/2.image\"],[\"Leather sandals\",22,\"Light sandals for warm afternoons.\",\"mens-shoes\",\"sports-shoes\",\"/products/3.image\"],[\"Summer dress\",32,\"A breezy dress for sunny days.\",\"womens-dresses\",\"black-women's-gown\",\"/products/4.image\"],[\"Wireless headphones\",48,\"Over-ear listening for study and travel.\",\"mobile-accessories\",\"amazon-echo-plus\",\"/products/5.image\"],[\"Bluetooth speaker\",29,\"Compact sound for your desk.\",\"mobile-accessories\",\"portable-speaker\",\"/products/6.image\"],[\"Wireless mouse\",12,\"A compact mouse for daily work.\",\"mobile-accessories\",\"wireless-mouse\",\"/products/7.image\"],[\"Power bank\",24,\"Portable charging for days away from home.\",\"mobile-accessories\",\"power-bank\",\"/products/8.image\"],[\"Charging cable\",6,\"A spare cable for your desk or bag.\",\"mobile-accessories\",\"apple-iphone-charger\",\"/products/9.image\"],[\"Basmati rice\",8,\"A 2 kg bag of fragrant rice for bariis.\",\"groceries\",\"rice\",\"/products/10.image\"],[\"Cooking oil\",5,\"A pantry staple for frying and sautéing.\",\"groceries\",\"cooking-oil\",\"/products/11.image\"],[\"Fresh bananas\",3,\"One bunch of ripe bananas.\",\"groceries\",\"banana\",\"/products/12.image\"],[\"Fresh mangoes\",4,\"Sweet mangoes for juice or a snack.\",\"groceries\",\"kiwi\",\"/products/13.image\"],[\"Milk\",2,\"One litre of milk for shaah or breakfast.\",\"groceries\",\"milk\",\"/products/14.image\"]];\nconst groups=['Fashion','Electronics','Food'];\r\nconst el=id=>document.getElementById(id), read=(key,def)=>JSON.parse(localStorage.getItem(key)||JSON.stringify(def)),save=(key,val)=>localStorage.setItem(key,JSON.stringify(val)),usd=n=>'$'+n.toFixed(2);\r\nlet cart=read('cart',{}),group='All';\r\nconst category=i=>groups[Math.floor(i/5)],photo=i=>'<img class=\"photo\" alt=\"'+data[i][0]+'\" loading=\"lazy\" decoding=\"async\" width=\"500\" height=\"400\" src=\"'+data[i][5]+'\" onerror=\"this.onerror=null;this.src=\\'/placeholder.svg\\'\">';\r\nfunction tile(i){return '<button class=\"tile\" onclick=\"detail('+i+')\">'+photo(i)+'<small>'+category(i)+'</small><span>'+data[i][0]+'</span><b>'+usd(data[i][1])+'</b></button>'}\r\nfunction render(){let ids=data.map((_,i)=>i).filter(i=>(group==='All'||category(i)===group)&&data[i][0].toLowerCase().includes(el('search').value.toLowerCase()));let sort=el('sort').selectedIndex;if(sort)ids.sort((a,b)=>(data[a][1]-data[b][1])*(sort===1?1:-1));el('products').innerHTML=ids.map(card).join('')||'No matching products.';el('filters').innerHTML=['All',...groups].map(g=>'<button class=\"'+(group===g?'active':'')+'\" onclick=\"group=this.textContent;render()\">'+g+'</button>').join(' ');el('bag').textContent='Cart ('+Object.values(cart).reduce((a,b)=>a+b,0)+')'}\r\nfunction show(html){el('panel').innerHTML=html;if(!el('modal').open)el('modal').showModal();el('modal').scrollTop=0}\r\nfunction detail(i){save('viewed',category(i));show('<h2>'+data[i][0]+'</h2>'+photo(i)+'<p>'+data[i][2]+'</p><p>In stock · '+usd(data[i][1])+'</p><button class=\"buy\" onclick=\"change('+i+',1)\">Add to cart</button><h3>Recommended for you</h3>'+data.map((_,j)=>j!==i&&category(j)===read('viewed','')?'<button onclick=\"detail('+j+')\">'+data[j][0]+'</button>':'').join(' '))}\r\nfunction change(i,n){cart[i]=(cart[i]||0)+n;if(cart[i]<=0)delete cart[i];save('cart',cart);render();basket()}\r\nconst total=()=>Object.entries(cart).reduce((s,[i,n])=>s+n*data[i][1],0);\r\nfunction basket(){show('<h2>Your cart</h2>'+ (total()?Object.entries(cart).map(([i,n])=>'<div class=\"row\">'+data[i][0]+' · '+usd(data[i][1]*n)+'<p><button aria-label=\"Decrease quantity\" onclick=\"change('+i+',-1)\">−</button> '+n+' <button aria-label=\"Increase quantity\" onclick=\"change('+i+',1)\">+</button> <button onclick=\"change('+i+',-'+n+')\">Remove</button></p></div>').join('')+'<p>Total <b>'+usd(total())+'</b></p><button class=\"buy\" onclick=\"checkout()\">Checkout</button>':'Your cart is empty.'))}\r\nel('bag').onclick=basket;el('search').oninput=el('sort').onchange=render;document.body.classList.toggle('dark',read('dark',false));el('theme').onclick=()=>save('dark',document.body.classList.toggle('dark'));render();\r\n\r\nfunction favorites(){return read('favorites',[])}\r\nfunction toggleSaved(i){const saved=favorites();save('favorites',saved.includes(i)?saved.filter(n=>n!==i):[...saved,i]);render()}\r\nfunction card(i){return '<article class=\"productwrap\">'+tile(i)+'<div class=\"actions\"><button onclick=\"change('+i+',1)\">Quick add</button><button aria-pressed=\"'+favorites().includes(i)+'\" onclick=\"toggleSaved('+i+')\">'+(favorites().includes(i)?'♥ Saved':'♡ Save')+'</button></div></article>'}\r\nel('saved').onclick=()=>show('<h2>Saved products</h2>'+(favorites().length?favorites().map(tile).join(''):'Save a product to find it here.'));\r\nasync function checkout(){\r\n try { const response=await fetch(\"/api/account\"); const account=await response.json(); if(!response.ok)throw Error(); if(!account.signedIn){show('<h2>Sign in to checkout</h2><p>Your orders will be saved to your account. Your cart is saved in this browser.</p><a class=\"primary\" href=\"/account?return=checkout\">Sign in with email</a>');return} } catch {show(\"<h2>Unable to check your account</h2><p>Please try again.</p>\");return}\r\n\r\n show('<h2>Checkout</h2><p>'+Object.entries(cart).map(([i,n])=>data[i][0]+' × '+n).join(' • ')+'</p><form id=\"order\">'+['Name','Phone','City','Address'].map(k=>'<label>'+k+'<input required maxlength=\"240\" '+(k==='Phone'?'type=\"tel\"':'')+'></label>').join('')+'<label>Payment method<select>'+['EVC Plus','Zaad','eDahab','Cash on delivery'].map(k=>'<option>'+k+'</option>').join('')+'</select></label><p>Demo checkout. Your delivery details are visible to the store admin. No payment is collected.</p><button class=\"buy\">Place order · '+usd(total())+'</button><p role=\"status\" id=\"error\"></p></form>');\r\n el('order').onsubmit=async e=>{\r\n e.preventDefault();const form=e.target,button=form.querySelector('button');button.disabled=true;\r\n const items=Object.entries(cart).map(([i,n])=>[Number(i),n]), customer=[...form.querySelectorAll('input')].map(f=>f.value.trim()),method=form.querySelector('select').value;\r\n const fingerprint=JSON.stringify([items,customer,method]),pending=read('pendingOrder',null);\r\n const id=pending?.fingerprint===fingerprint?pending.id:'XM-'+crypto.randomUUID().toUpperCase();save('pendingOrder',{id,fingerprint});\r\n try{const r=await fetch('/api/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,items,customer,method})});\r\n if(!r.ok)throw Error((await r.json()).error);\r\n save('pendingOrder',null);cart={};save('cart',cart);render();show('<h2>Order confirmed</h2><p>Use this number to track your order:</p><b>'+id+'</b><p><a href=\"/account\">View my orders →</a></p>');\r\n }catch(err){el('error').textContent=err.message;button.disabled=false}\r\n };\r\n}\r\nel('track').onclick=()=>{\r\n show('<h2>Track your order</h2><form id=\"lookup\"><label>Order number<input required id=\"number\" placeholder=\"XM-…\"></label><button>Find order</button></form><p id=\"status\" role=\"status\"></p>');\r\n el('lookup').onsubmit=async e=>{e.preventDefault();const id=el('number').value.trim().toUpperCase(),legacy=read('orders',{})[id];if(legacy){el('status').textContent='Order received · '+usd(legacy.amount)+' · '+legacy.method;return}\r\n try{const r=await fetch('/api/track/'+encodeURIComponent(id)),o=await r.json();el('status').textContent=r.ok?o.status+' · '+usd(o.total)+' · '+o.method:o.error}catch{el('status').textContent='Tracking is unavailable. Please try again.'}};\r\n}\r\nfunction browse(department){group=department;el('search').value='';render()}\r\n"],"/admin.js":["text/javascript; charset=utf-8","const workspace = document.querySelector('#workspace');\r\nconst message = document.querySelector('#message');\r\nconst statuses = ['Received', 'Packing', 'Shipped', 'Delivered', 'Cancelled'];\r\nconst esc = value => String(value).replace(/[&<>\"']/g, character => ({\r\n  '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;'\r\n}[character]));\r\nconst money = value => '$' + value.toFixed(2);\r\nlet orders = [];\r\nlet query = '';\r\nlet selectedStatus = 'All';\r\n\r\nasync function call(action, body) {\r\n  const response = await fetch('/api/admin/' + action, body ? {\r\n    method: 'POST',\r\n    headers: { 'Content-Type': 'application/json' },\r\n    body: JSON.stringify(body)\r\n  } : {});\r\n  const result = await response.json();\r\n  if (!response.ok) throw Object.assign(Error(result.error), { status: response.status });\r\n  return result;\r\n}\r\n\r\nfunction renderOrders() {\r\n  const matching = orders.filter(order =>\r\n    (selectedStatus === 'All' || order.status === selectedStatus) &&\r\n    (order.id + order.customer).toLowerCase().includes(query.toLowerCase())\r\n  );\r\n  document.querySelector('#count').textContent = matching.length + ' orders';\r\n  document.querySelector('#list').innerHTML = matching.map(order => {\r\n    const [name, phone, city, address] = JSON.parse(order.customer);\r\n    const items = JSON.parse(order.items);\r\n    return '<article class=\"orderrow\"><div class=\"orderheading\"><div><b>' + esc(name) +\r\n      '</b><small>' + esc(city) + ' · ' + esc(order.created) + ' UTC</small></div>' +\r\n      '<span class=\"badge ' + esc(order.status) + '\">' + esc(order.status) + '</span>' +\r\n      '<b>' + money(order.total) + '</b></div><details><summary>View order details</summary>' +\r\n      '<p class=\"orderid\">' + esc(order.id) + '</p><div class=\"detailgrid\"><section><h3>Delivery</h3>' +\r\n      '<p>' + esc(phone) + '</p><p>' + esc(address) + ', ' + esc(city) + '</p></section>' +\r\n      '<section><h3>Items</h3><ul>' + items.map(item => '<li>' + esc(item.name) + ' × ' + item.qty +\r\n        ' · ' + money(item.qty * item.price) + '</li>').join('') + '</ul><p>' + esc(order.method) +\r\n      ' · Simulated payment</p></section></div><label>Update fulfillment<select data-id=\"' +\r\n      esc(order.id) + '\">' + statuses.map(status => '<option ' + (order.status === status ? 'selected' : '') +\r\n        '>' + status + '</option>').join('') + '</select></label></details></article>';\r\n  }).join('') || '<div class=\"empty\"><h3>No orders to show</h3><p>' +\r\n    (orders.length ? 'Try a different status or search.' : 'Customer purchases will appear here after checkout.') + '</p></div>';\r\n}\r\n\r\nasync function dashboard() {\r\n  orders = await call('orders');\r\n  document.body.classList.add('unlocked');\r\n  document.querySelector('#heading').textContent = 'Store overview';\r\n  message.textContent = '';\r\n  const metrics = [\r\n    ['Total orders', orders.length],\r\n    ['To pack', orders.filter(order => order.status === 'Received').length],\r\n    ['On the way', orders.filter(order => order.status === 'Shipped').length],\r\n    ['Active order value', money(orders.filter(order => order.status !== 'Cancelled').reduce((sum, order) => sum + order.total, 0))]\r\n  ];\r\n  workspace.innerHTML = '<section class=\"metrics\">' + metrics.map(([label, value]) =>\r\n    '<article><span>' + label + '</span><strong>' + value + '</strong></article>').join('') +\r\n    '</section><div class=\"sectiontitle\"><h2 id=\"orderlist\">Orders</h2><span id=\"count\"></span></div>' +\r\n    '<div class=\"toolbar\"><input id=\"find\" aria-label=\"Search orders\" placeholder=\"Search customer, city or order number\">' +\r\n    '<button id=\"refresh\">Refresh orders</button><button id=\"lock\">Lock dashboard</button></div>' +\r\n    '<div class=\"statusfilters\" role=\"group\" aria-label=\"Filter by order status\">' +\r\n    ['All', ...statuses].map(status => '<button data-status=\"' + status + '\" aria-pressed=\"' +\r\n      (status === selectedStatus) + '\">' + status + '</button>').join('') + '</div><section id=\"list\"></section>';\r\n  const search = document.querySelector('#find');\r\n  search.value = query;\r\n  search.oninput = () => { query = search.value; renderOrders(); };\r\n  document.querySelector('.statusfilters').onclick = event => {\r\n    const status = event.target.dataset.status;\r\n    if (!status) return;\r\n    selectedStatus = status;\r\n    document.querySelectorAll('[data-status]').forEach(button =>\r\n      button.setAttribute('aria-pressed', button.dataset.status === selectedStatus));\r\n    renderOrders();\r\n  };\r\n  document.querySelector('#list').onchange = async event => {\r\n    const field = event.target;\r\n    const previous = orders.find(order => order.id === field.dataset.id);\r\n    if (!previous) return;\r\n    field.disabled = true;\r\n    try {\r\n      await call('status', { id: field.dataset.id, status: field.value });\r\n      await dashboard();\r\n      message.textContent = 'Order status updated.';\r\n    } catch (error) {\r\n      field.value = previous.status;\r\n      field.disabled = false;\r\n      message.textContent = error.message;\r\n    }\r\n  };\r\n  document.querySelector('#refresh').onclick = async () => {\r\n    try { await dashboard(); } catch (error) { message.textContent = error.message; }\r\n  };\r\n  document.querySelector('#lock').onclick = async () => {\r\n    try { await call('logout', {}); await init(); } catch (error) { message.textContent = error.message; }\r\n  };\r\n  renderOrders();\r\n}\r\n\r\nasync function init() {\r\n  workspace.replaceChildren();\r\n  document.body.classList.remove('unlocked');\r\n  document.querySelector('#heading').textContent = 'Welcome back';\r\n  try {\r\n    const state = await call('state');\r\n    if (state.active) { await dashboard(); return; }\r\n    location.replace('/account');\r\n  } catch (error) {\r\n    message.textContent = error.message;\r\n\r\n  }\r\n}\r\ninit();\r\n"],"/style.css":["text/css; charset=utf-8","*{box-sizing:border-box}html{scroll-behavior:smooth}a{color:inherit}body{font-family:system-ui,sans-serif}.hero{padding:clamp(28px,5vw,72px);border-radius:4px;background:linear-gradient(90deg,#12342deb 2%,#12342db8 50%,#12342d25),url('https://images.unsplash.com/photo-1542838132-92c53300491e?w=1600&q=85') center/cover}.hero:after{display:none}.hero small{letter-spacing:.17em}.hero h1{letter-spacing:-.055em}.hero button,.buy,.primary{border-radius:24px;padding:12px 24px}.productwrap{background:var(--card);border:1px solid #80988a40;border-radius:14px;overflow:hidden;display:flex;flex-direction:column}.productwrap .tile{box-shadow:none;border-radius:0;flex:1}.photo{object-fit:contain}.actions{display:flex;justify-content:space-between;padding:8px 12px 14px;gap:5px}.actions button{border-radius:22px;font-size:14px}.actions button:first-child{background:#1b503d;color:white}.grid{gap:20px}.tools{padding:14px;background:var(--card);border-radius:14px}.tools input{border:0;border-bottom:1px solid #829487;border-radius:0}#filters button{border-radius:20px}footer a{font-size:14px}.desk{margin:0;background:#f4f5ee;color:#1d4134}.desk header,.desk main{max-width:1120px;margin:auto;padding:22px 5%}.desk header,.toolbar,.metrics{display:flex;gap:12px;justify-content:space-between;flex-wrap:wrap}.desk header{border-bottom:1px solid #c7cfc5}.desk h1{font:clamp(42px,7vw,72px) Georgia;margin:25px 0}.desk button,.desk input,.desk select,.primary{font:inherit;padding:10px;border-radius:8px;border:1px solid #94a899}.primary,.desk button{background:#184833;color:white}.metrics article,.ordercard,.desk form{padding:20px;background:white;border-radius:14px;margin:12px 0}.metrics article{flex:1;min-width:145px}.metrics strong{font:36px Georgia;display:block}.toolbar input{flex:1}.desk label{display:grid;gap:6px;margin:12px 0}.ordercard small{color:#516455}.ordercard h2{margin:8px 0}.desk form{max-width:440px}button{cursor:pointer}@media(max-width:560px){footer{flex-wrap:wrap;gap:12px}.photo{height:150px}.grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.actions{flex-wrap:wrap}.tile span{font-size:17px}.actions button{font-size:12px}}\r\n.brand{font:700 31px/1 Georgia,serif;letter-spacing:-1.8px;text-decoration:none}.brand span{font-weight:400;font-style:italic}.store{--bg:#f9f6ee;--ink:#203b30}.store.dark{--bg:#172c25;--ink:#f6f2de}.store header{border-bottom:1px solid #89978266;padding-block:23px}.store header nav{gap:20px}.store header nav a{text-decoration:none;font-size:14px;font-weight:600}.store header nav a:hover,.shopfoot a:hover{text-decoration:underline}.utility{display:flex;gap:4px}.utility button{border:0;background:transparent}.utility #bag,.cta{background:#244635;color:#fff;border-radius:24px}.cover{display:grid;grid-template-columns:1fr 1fr;background:#e8e7c9;color:#213f30;overflow:hidden;border-radius:4px}.cover>div{padding:clamp(26px,5vw,72px)}.cover small,.desk aside small{font-size:11px;font-weight:700;letter-spacing:.16em}.cover h1{font-size:clamp(50px,6.7vw,91px);letter-spacing:-.065em;line-height:.92;margin:28px 0 18px}.cover h1 em{font-weight:400}.cover p{max-width:340px;line-height:1.6}.cta{display:inline-block;text-decoration:none;padding:13px 21px;margin-top:8px;font-weight:600}.cover figure{position:relative;margin:0;background:#69836c;min-height:250px}.cover img{position:absolute;width:100%;height:100%;object-fit:cover}.cover figcaption{position:absolute;bottom:12px;left:12px;right:12px;display:flex;justify-content:space-between;align-items:center;padding:10px 14px;background:#fffff3ec;color:#233f30;border-radius:3px;font:20px Georgia}.cover figcaption a{text-decoration:none;padding:4px 9px}.store #shop{margin:45px 0 18px;letter-spacing:-1.4px}.productwrap{border-radius:5px}.productwrap:hover{box-shadow:0 5px 15px #28483718}.photo{background:#edece1}.store .tools{border:1px solid #889b854d;border-radius:5px}.store .shopfoot{margin:40px 0 0;max-width:none;background:#193a2e;color:#faf8eb;align-items:flex-start;display:grid;grid-template-columns:2fr repeat(3,1fr);padding:42px max(5%,calc((100vw - 1130px)/2));gap:24px}.shopfoot div{display:grid;justify-items:start;gap:8px}.shopfoot b{color:#d7ddab;margin-bottom:8px}.shopfoot a,.shopfoot button{color:inherit;text-decoration:none}.shopfoot button{border:0;padding:0;background:none;text-align:left;font-size:14px}.shopfoot p,.shopfoot small{line-height:1.6;color:#d2dfd4}.desk{min-height:100vh;display:grid;grid-template-columns:220px minmax(0,1fr);background:#f7f7f2;color:#263831}.desk aside{padding:32px 22px;background:#18392e;color:#fff;display:flex;flex-direction:column;gap:26px}.desk aside small{margin-top:32px;color:#c7d5a2}.desk aside nav{display:grid;gap:5px}.desk aside nav a,.desk .back{padding:12px;text-decoration:none;border-radius:5px}.desk aside nav a:first-child,.desk aside nav a:hover{background:#315544}.desk .signed{display:none}.desk.unlocked .signed{display:block}.desk .back{margin-top:auto}.deskpage{display:flex;flex-direction:column;min-width:0}.desk header,.desk main,.desk footer{width:100%;max-width:1300px}.desk header,.desk footer{padding:20px 5%;font-size:14px}.desk footer{display:flex;justify-content:space-between;gap:10px;border-top:1px solid #cdd4ca;margin:auto auto 0}.desk h1{font:600 clamp(36px,4vw,52px)/1.1 system-ui;letter-spacing:-.055em}.console{padding:clamp(16px,3vw,32px);background:white;border:1px solid #d8ded5;border-radius:12px}.console form{padding:0;margin:0}.console #message:empty{display:none}.desk .primary{display:inline-block;padding:12px 20px;text-decoration:none}.desk details{max-width:650px;margin:24px 0;line-height:1.7}.desk summary{cursor:pointer;font-weight:600}.metrics article{background:#edf1e3;border-radius:8px}.ordercard{border:1px solid #d3dbcd}.ordercard p{overflow-wrap:anywhere}.desk .empty{background:#f4f6f1;padding:22px;border-radius:7px}.desk a:focus-visible,button:focus-visible,a:focus-visible{outline:3px solid #b78339;outline-offset:3px}@media(max-width:800px){.store header nav{order:3;width:100%;justify-content:space-between}.desk{grid-template-columns:1fr}.desk aside{padding:16px 5%;gap:14px}.desk aside small,.desk .back{display:none}.desk aside nav{display:flex;flex-wrap:wrap}.desk aside nav a{padding:7px 12px}.store .shopfoot{grid-template-columns:1fr 1fr}}@media(max-width:560px){.cover{grid-template-columns:1fr}.cover figure{min-height:190px}.cover>div{padding:26px}.cover h1{margin:16px 0}.store header{gap:9px;padding-block:14px}.store .brand{font-size:26px}.utility button{padding:7px;font-size:14px}.desk footer{flex-wrap:wrap}.shopfoot{font-size:14px}}\r\n.accountlink{padding:9px 10px;font-size:14px;text-decoration:none}.customer{display:flex;flex-direction:column;min-height:100vh}.customer header{align-items:center}.customer nav{display:flex;gap:20px}.customer main{max-width:960px;margin:auto}.customer footer{margin-top:auto}.customer .orderheading{gap:12px;flex-wrap:wrap}.orderheading{display:flex;justify-content:space-between;align-items:center;gap:20px}.orderheading small{display:block;font-size:12px;color:#67746b;margin-top:5px}.badge{display:inline-block;border-radius:20px;padding:6px 12px;font-size:12px;background:#edf1e9;color:#345347;font-weight:600}.badge.Received{background:#fff0d2;color:#755219}.badge.Shipped{background:#e2eefb;color:#244f7b}.badge.Delivered{background:#e1f3df;color:#2e632d}.badge.Cancelled{background:#f6e4e2;color:#803c35}.progress{display:flex;gap:5px;list-style:none;padding:0;margin:25px 0}.progress li{flex:1;border-top:4px solid #e0e6dd;padding-top:10px;color:#657369;font-size:13px}.progress .reached{border-color:#326348;color:#254733;font-weight:600}.customer .ordercard ul{padding-left:20px;line-height:1.9}.legacy-note{color:#667466;font-size:13px;margin:28px 0}.sectiontitle{display:flex;justify-content:space-between;align-items:center}.sectiontitle span{font-size:13px;color:#6d796d}.statusfilters{display:flex;gap:7px;flex-wrap:wrap;margin:20px 0}.desk .statusfilters button{background:#f5f7f1;color:#425e4a;border:1px solid #e0e6da;border-radius:20px;padding:7px 13px;font-size:13px}.desk .statusfilters button[aria-pressed=true]{background:#203f30;color:#fff}.orderrow{border:1px solid #e1e6dd;border-radius:9px;padding:20px;margin:12px 0}.orderrow details{margin:15px 0 0;max-width:none}.orderrow summary{font-size:13px}.orderrow h3{font-size:13px;color:#6a786d}.orderid{font-size:12px;overflow-wrap:anywhere}.detailgrid{display:grid;grid-template-columns:1fr 1fr;gap:22px}.detailgrid ul{padding-left:18px;font-size:14px}.desk .metrics{gap:12px}.desk .metrics article{margin-top:0;background:#f3f5ee;border:1px solid #e0e6d9}.desk .metrics span{font-size:12px;color:#66755f}.desk .metrics strong{font:600 32px system-ui;margin-top:14px;letter-spacing:-1px}.desk .toolbar button{font-size:13px}.desk .loginform{margin-top:25px;max-width:400px}.loginform button{width:100%}@media(max-width:560px){.detailgrid{grid-template-columns:1fr;gap:5px}.orderheading{flex-wrap:wrap;gap:10px}.desk .metrics article{min-width:120px}.progress{flex-wrap:wrap}.progress li{min-width:40%}.store .utility{flex-wrap:wrap}.customer header nav{font-size:13px}.orderrow{padding:14px}}\r\n.authlinks{display:flex;flex-wrap:wrap;gap:8px;margin-top:24px}.authlinks button{font-size:13px;background:transparent;color:#244635;border:0;text-decoration:underline}\r\n"],"/placeholder.svg":["image/svg+xml; charset=utf-8","<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 240\"><rect width=\"400\" height=\"240\" fill=\"#dce6d5\"/><path d=\"M150 90h100l9 96H141z M175 91q0-58 50 0\" fill=\"none\" stroke=\"#49745c\" stroke-width=\"6\"/><text x=\"200\" y=\"152\" text-anchor=\"middle\" font-family=\"Georgia\" font-size=\"34\" fill=\"#315841\">XM</text></svg>\r\n"],"/chatbot.js":["text/javascript; charset=utf-8","import {answer} from './chatbot-core.js';\nconst root=document.createElement('div');\nroot.innerHTML=`<button class=\"chat-launcher\" id=\"chat-launcher\" aria-expanded=\"false\" aria-controls=\"chat-window\"><span aria-hidden=\"true\">✦</span> Chat with us</button>\n<section class=\"chat-window\" id=\"chat-window\" aria-label=\"Xarun shopping assistant\" hidden>\n <div class=\"chat-heading\"><div><b>Xarun assistant</b><small>Product & shopping help</small></div><button id=\"chat-close\" aria-label=\"Close chat\">×</button></div>\n <div class=\"chat-messages\" id=\"chat-messages\" role=\"log\" aria-live=\"polite\" aria-relevant=\"additions\" tabindex=\"0\"></div>\n <div class=\"chat-suggestions\" aria-label=\"Suggested questions\"><button>Products under $20</button><button>Payment options</button><button>Track my order</button></div>\n <form class=\"chat-form\" id=\"chat-form\"><label class=\"visually-hidden\" for=\"chat-input\">Your message</label><input id=\"chat-input\" placeholder=\"Ask about the market…\" maxlength=\"400\" autocomplete=\"off\" required><button type=\"submit\" aria-label=\"Send message\">Send ↑</button></form>\n <p class=\"chat-note\">Automated store helper · No live agent</p>\n</section>`;\ndocument.body.append(root);\nconst get=id=>document.getElementById(id),log=get('chat-messages');\nlet returnFocus;\nfunction toggle(open){get('chat-window').hidden=!open;get('chat-launcher').setAttribute('aria-expanded',String(open));if(open){returnFocus=document.activeElement;get('chat-input').focus()}else{returnFocus?.focus()}}\nfunction message(text,who='assistant'){\n const item=document.createElement('div');item.className='chat-message '+who;\n const label=document.createElement('small');label.textContent=who==='user'?'You':'Xarun assistant';\n const p=document.createElement('p');p.textContent=text;item.append(label,p);log.append(item);\n while(log.children.length>60)log.firstElementChild.remove();\n return item;\n}\nfunction ask(text){\n text=text.trim().slice(0,400);if(!text)return;\n message(text,'user');get('chat-input').value='';\n const reply=answer(text,data,cart),item=message(reply.text);\n for(const i of reply.ids){\n  const button=document.createElement('button');button.className='chat-product';\n  const img=document.createElement('img');img.src=data[i][5];img.alt='';img.loading='lazy';\n  const span=document.createElement('span');span.textContent=data[i][0]+' · $'+data[i][1].toFixed(2);\n  button.append(img,span);button.onclick=()=>{toggle(false);detail(i)};item.append(button);\n }\n if(reply.action){const button=document.createElement('button');button.className='chat-action';button.textContent={track:'Track an order →',account:'My account →',cart:'View cart →'}[reply.action];button.onclick=()=>{toggle(false);if(reply.action==='account')location.href='/account';else if(reply.action==='track')get('track').click();else basket()};item.append(button)}\n log.scrollTop=log.scrollHeight;get('chat-input').focus();\n}\nmessage('Hello! Salaam! Welcome to Xarun Market. I can help you find products, check prices and understand checkout. What can I help you with?');\nget('chat-launcher').onclick=()=>toggle(get('chat-window').hidden);\nget('chat-close').onclick=()=>toggle(false);\nget('help').onclick=()=>toggle(true);\nget('chat-form').onsubmit=e=>{e.preventDefault();ask(get('chat-input').value)};\nroot.querySelectorAll('.chat-suggestions button').forEach(button=>button.onclick=()=>ask(button.textContent));\nroot.addEventListener('keydown',e=>{if(e.key==='Escape'&&!get('chat-window').hidden){e.preventDefault();toggle(false)}});\n"],"/chatbot-core.js":["text/javascript; charset=utf-8","// Catalog-grounded replies. No external service or customer data transmission.\nexport function answer(question, catalog, cart = {}) {\n const q=question.toLowerCase().trim();\n const money=n=>'$'+n.toFixed(2);\n const result=(text,ids=[],action=null)=>({text,ids,action});\n if(/\\b(track|tracking|status|dalab)\\b/.test(q))return result('Use Track an order with your XM order number, or sign in to My account to see your orders. I cannot look up private order details in this chat.',[],'track');\n if(/\\b(pay|payment|payments|evc|zaad|edahab|cash|lacag)\\b/.test(q))return result('Checkout offers EVC Plus, Zaad, eDahab and cash on delivery. This store currently uses demo checkout: no real payment is collected.');\n if(/\\b(delivery|shipping|deliver|return|refund)\\b/.test(q))return result('Delivery times, shipping fees and returns policies are not listed yet. Please confirm these with the store before ordering; I cannot promise a delivery date or refund.');\n if(/\\b(account|login|sign in|password|register)\\b/.test(q))return result('Open My account to register or sign in. Registration sends an email link to verify your email and choose a password. Forgot password is available there too.',[],'account');\n if(/\\b(cart|basket|checkout)\\b/.test(q)){\n  const entries=Object.entries(cart).filter(([i,n])=>catalog[i]&&n>0);\n  return result(entries.length?'Your cart: '+entries.map(([i,n])=>`${catalog[i][0]} × ${n}`).join(', ')+'. Total: '+money(entries.reduce((sum,[i,n])=>sum+catalog[i][1]*n,0))+'. Sign in to proceed with demo checkout.':'Your cart is empty. Browse the products below and use Quick add to start.',[],'cart');\n }\n const aliases=[['t-shirt','tee'],['tshirt','tee'],['bariis','rice'],['moos','bananas'],['caano','milk'],['cambe','mangoes'],['saliid','oil'],['headset','headphones'],['bag','tote'],['bags','tote'],['charger','charging'],['pantry','food']];\n let normalized=q;for(const [a,b]of aliases)normalized=normalized.replaceAll(a,b);\n const groups=['Fashion','Electronics','Food'];\n const stop=new Set(['i','a','an','the','you','your','have','has','do','does','is','are','me','my','show','find','want','need','please','can','some','for','of','to','buy','price','cost','how','much','what','which','under','below','less','than','over','above','between','and','dollars','usd','products','product','recommend','something','cheap','cheapest','affordable','budget','with']);\n const terms=normalized.match(/[a-z]+/g)?.filter(t=>!stop.has(t))||[];\n const budget=normalized.match(/(?:under|below|less than|budget(?: of)?)\\s*\\$?\\s*(\\d+(?:\\.\\d+)?)/);\n const lower=normalized.match(/(?:over|above)\\s*\\$?\\s*(\\d+(?:\\.\\d+)?)/);\n let ids=catalog.map((_,i)=>i).filter(i=>{\n  const text=(catalog[i][0]+' '+groups[Math.floor(i/5)]).toLowerCase();\n  return (!terms.length||terms.some(t=>text.includes(t)))&&(!budget||catalog[i][1]<Number(budget[1]))&&(!lower||catalog[i][1]>Number(lower[1]));\n });\n if(/cheap|budget|affordable|lowest/.test(q)||budget)ids.sort((a,b)=>catalog[a][1]-catalog[b][1]);\n if(terms.length||budget||lower||/products|recommend|cheap|shop|browse/.test(q))return ids.length?result('Here '+(ids.length===1?'is a matching product':'are some matching products')+'. Prices are in USD. Select a product for details.',ids.slice(0,5)):result('I couldn’t find a matching product. Try a product name, Fashion, Electronics, Food, or “products under $20”.');\n if(/^(hi|hello|hey|salaam|asc|thanks|thank you)[!. ]*$/.test(q))return result('Hello! Salaam! I can help you find products, compare prices, view your cart or find order help. What are you shopping for?');\n return result('I’m the automated store helper. Try “headphones”, “food under $10”, “my cart”, “payment” or “track my order”. I can only answer using this store’s catalog and listed information.');\n}\n"],"/chatbot.css":["text/css; charset=utf-8",".chat-launcher{position:fixed;bottom:22px;right:22px;z-index:20;background:#244635;color:#fff;border:1px solid #72917a;border-radius:28px;padding:14px 20px;box-shadow:0 5px 25px #102b2330;font-weight:650;display:flex;align-items:center;gap:10px}.chat-launcher span{color:#e4efac;font-size:23px}.chat-window{position:fixed;right:22px;bottom:92px;width:min(390px,calc(100vw - 24px));max-height:min(650px,calc(100dvh - 110px));z-index:21;background:var(--card);color:var(--ink);border:1px solid #80988a70;border-radius:18px;box-shadow:0 15px 55px #102b2338;overflow:hidden;display:flex;flex-direction:column}.chat-window[hidden]{display:none}.chat-heading{background:#244635;color:#fff;display:flex;justify-content:space-between;align-items:center;padding:17px 18px}.chat-heading b{font-size:18px}.chat-heading small{display:block;font-size:12px;color:#d6e4d8;margin-top:4px}.chat-heading button{background:transparent;color:white;border:0;font-size:26px;padding:0 6px}.chat-messages{overflow:auto;min-height:150px;flex:1;padding:16px;overscroll-behavior:contain}.chat-message{background:var(--bg);border:1px solid #80988a30;border-radius:12px 12px 12px 3px;padding:12px;margin-bottom:12px;max-width:94%;overflow-wrap:anywhere}.chat-message small{font-size:11px;font-weight:700;opacity:.75}.chat-message p{font-size:14px;line-height:1.55;margin:5px 0 0}.chat-message.user{background:#244635;color:#fff;margin-left:auto;border-radius:12px 12px 3px 12px}.chat-suggestions{display:flex;gap:6px;padding:6px 14px 12px;flex-wrap:wrap}.chat-suggestions button{font-size:11px;border-radius:20px;padding:6px 9px}.chat-form{display:flex;gap:7px;padding:12px;border-top:1px solid #80988a40}.chat-form input{min-width:0;flex:1;font-size:14px}.chat-form button{background:#244635;color:white;font-size:13px}.chat-note{font-size:10px;text-align:center;opacity:.7;margin:0 0 12px}.chat-product{display:flex;align-items:center;gap:10px;width:100%;text-align:left;margin-top:8px;padding:7px;font-size:13px}.chat-product img{width:42px;height:42px;object-fit:contain;background:white;border-radius:5px}.chat-action{font-size:13px;margin-top:10px}.visually-hidden{position:absolute;width:1px;height:1px;padding:0;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.store .photo{background:#fff;padding:12px}.shopfoot{padding-bottom:95px!important}@media(max-width:560px){.chat-launcher{right:12px;bottom:12px;padding:10px 16px}.chat-window{right:12px;bottom:75px;max-height:calc(100dvh - 90px)}.chat-form input{font-size:16px}.chat-messages{min-height:80px}}\n"],"/products/0.image":["image/png","","base64"],"/products/1.image":["image/webp","","base64"],"/products/2.image":["image/webp","","base64"],"/products/3.image":["image/jpeg","","base64"],"/products/4.image":["image/webp","","base64"],"/products/5.image":["image/jpeg","","base64"],"/products/6.image":["image/jpeg","","base64"],"/products/7.image":["image/jpeg","","base64"],"/products/8.image":["image/png","","base64"],"/products/9.image":["image/jpeg","","base64"],"/products/10.image":["image/webp","","base64"],"/products/11.image":["image/webp","","base64"],"/products/12.image":["image/jpeg","","base64"],"/products/13.image":["image/jpeg","","base64"],"/products/14.image":["image/webp","","base64"]};
const catalog=[["Cotton everyday tee",14,"Soft cotton with an easy, relaxed fit.","tops","tshirt","/products/0.image"],["Canvas tote",18,"A roomy carryall for market days.","womens-bags","blue-womens-handbag","/products/1.image"],["Classic watch",36,"A simple everyday timepiece.","mens-watches","brown-leather-belt-watch","/products/2.image"],["Leather sandals",22,"Light sandals for warm afternoons.","mens-shoes","sports-shoes","/products/3.image"],["Summer dress",32,"A breezy dress for sunny days.","womens-dresses","black-women's-gown","/products/4.image"],["Wireless headphones",48,"Over-ear listening for study and travel.","mobile-accessories","amazon-echo-plus","/products/5.image"],["Bluetooth speaker",29,"Compact sound for your desk.","mobile-accessories","portable-speaker","/products/6.image"],["Wireless mouse",12,"A compact mouse for daily work.","mobile-accessories","wireless-mouse","/products/7.image"],["Power bank",24,"Portable charging for days away from home.","mobile-accessories","power-bank","/products/8.image"],["Charging cable",6,"A spare cable for your desk or bag.","mobile-accessories","apple-iphone-charger","/products/9.image"],["Basmati rice",8,"A 2 kg bag of fragrant rice for bariis.","groceries","rice","/products/10.image"],["Cooking oil",5,"A pantry staple for frying and sautéing.","groceries","cooking-oil","/products/11.image"],["Fresh bananas",3,"One bunch of ripe bananas.","groceries","banana","/products/12.image"],["Fresh mangoes",4,"Sweet mangoes for juice or a snack.","groceries","kiwi","/products/13.image"],["Milk",2,"One litre of milk for shaah or breakfast.","groceries","milk","/products/14.image"]];
const json=(value,status=200,headers={})=>new Response(JSON.stringify(value),{status,headers:{'content-type':'application/json','cache-control':'no-store',...headers}});
const fail=(message,status=400)=>json({error:message},status);
const hex=bytes=>Array.from(new Uint8Array(bytes),n=>n.toString(16).padStart(2,'0')).join('');
async function digest(password,salt){
 const encoder=new TextEncoder();
 const key=await crypto.subtle.importKey('raw',encoder.encode(password),'PBKDF2',false,['deriveBits']);
 return hex(await crypto.subtle.deriveBits({name:'PBKDF2',hash:'SHA-256',salt:encoder.encode(salt),iterations:600000},key,256));
}
const statuses=['Received','Packing','Shipped','Delivered','Cancelled'];
async function api(request,env,path){
 if(!['GET','POST'].includes(request.method))return fail('Method not allowed',405);
 if(Number(request.headers.get('content-length'))>20000)return fail('Request too large',413);
 const post=request.method==='POST';
 if(post && request.headers.get('origin')!==new URL(request.url).origin)return fail('Invalid origin',403);
 const db=env.DB;
 const customerSession=await session(request,db,'customer');
 const userId=customerSession?.user_id;
 if(path==='/api/account'){
  const admin=await session(request,db,'admin');
  const isAdmin=!!env.ADMIN_EMAIL&&typeof env.ADMIN_PASSWORD==='string'&&env.ADMIN_PASSWORD.length>=12&&admin?.user_id===await sha(env.ADMIN_EMAIL.toLowerCase()+'|'+env.ADMIN_PASSWORD);
  return json({signedIn:!!userId||isAdmin,role:isAdmin?'admin':userId?'customer':null});
 }
 if(path==='/api/account/orders'){
  if(!userId)return fail('Sign in to view your orders.',401);
  return json((await db.prepare('SELECT id,created,items,total,method,status FROM orders WHERE user_id=? ORDER BY created DESC,id DESC').bind(userId).all()).results);
 }
 const input=post?await request.json():{};
 if(path.startsWith('/api/auth/'))return customerAuth(request,env,path,input);
 if(path==='/api/orders' && post){
  if(!userId)return fail('Sign in before placing an order.',401);
  const {id,items,customer,method}=input;
  if(!/^XM-[0-9a-f-]{36}$/i.test(id)||!Array.isArray(items)||!items.length||items.length>catalog.length||!Array.isArray(customer)||customer.length!==4||!customer.every(s=>typeof s==='string'&&s.trim().length&&s.length<=240)||!['EVC Plus','Zaad','eDahab','Cash on delivery'].includes(method))return fail('Check your order details.');
  if(!items.every(([i,n])=>Number.isInteger(i)&&catalog[i]&&Number.isInteger(n)&&n>0&&n<=99))return fail('Maximum 99 of each item.');
  const lines=items.map(([i,n])=>({name:catalog[i][0],qty:n,price:catalog[i][1]}));
  const total=lines.reduce((sum,x)=>sum+x.qty*x.price,0);
  await db.prepare('INSERT INTO orders(id,customer,items,total,method,user_id) VALUES(?,?,?,?,?,?) ON CONFLICT(id) DO NOTHING').bind(id,JSON.stringify(customer),JSON.stringify(lines),total,method,userId).run();
  const owner=await db.prepare('SELECT user_id FROM orders WHERE id=?').bind(id).first();
  if(owner.user_id!==userId)return fail('Choose a new order number.',409);
  return json({id});
 }
 if(path.startsWith('/api/track/')&&!post){
  const row=await db.prepare('SELECT status,total,method FROM orders WHERE id=? AND (user_id IS NULL OR user_id=?)').bind(path.slice(11),userId).first();
  return row?json(row):fail('Order not found.',404);
 }
 if(!path.startsWith('/api/admin/'))return fail('Not found',404);
 const configured=!!env.ADMIN_EMAIL && typeof env.ADMIN_PASSWORD==='string' && env.ADMIN_PASSWORD.length>=12;
 const active=await session(request,db,'admin');
 const validAdmin=configured && active && active.user_id===await sha(env.ADMIN_EMAIL.toLowerCase()+'|'+env.ADMIN_PASSWORD);
 if(path==='/api/admin/state')return json({configured,active:!!validAdmin});
 if(path==='/api/admin/login'&&post){
  if(!configured)return fail('Admin login needs server configuration.',503);
  if(!await allowLogin(request,db,input.email))return fail('Too many attempts. Try again in 15 minutes.',429);
  const email=String(input.email||'').trim().toLowerCase();
  if(typeof input.password!=='string'||input.password.length>128)return fail('Incorrect email or password.',401);
  const actual=await sha(email+'|'+input.password);
  const expected=await sha(env.ADMIN_EMAIL.toLowerCase()+'|'+env.ADMIN_PASSWORD);
  if(!equal(actual,expected))return fail('Incorrect email or password.',401);
  return createSession(request,db,'admin',expected);
 }
 if(!validAdmin)return fail('Sign in as admin.',401);
 if(path==='/api/admin/logout'&&post)return endSession(request,db,'admin');
 if(path.endsWith('/orders')&&!post)return json((await db.prepare('SELECT * FROM orders ORDER BY created DESC,id DESC').all()).results);
 if(path.endsWith('/status')&&post&&statuses.includes(input.status)){
  const r=await db.prepare('UPDATE orders SET status=? WHERE id=?').bind(input.status,input.id).run();
  return r.meta.changes?json({ok:true}):fail('Order not found.',404);
 }
 return fail('Unknown action');
}
export default {async fetch(request,env){
 const path=new URL(request.url).pathname;
 if(path.startsWith('/api/')){try{return await api(request,env,path)}catch{return fail('Request failed. Please try again.',500)}}
 const asset=assets[path];return asset?new Response(asset[2]==='base64'?Uint8Array.from(atob(asset[1]),c=>c.charCodeAt(0)):asset[1],{headers:{'Content-Type':asset[0],'Referrer-Policy':'no-referrer','Cache-Control':asset[2]==='base64'?'public, max-age=3600':'no-store'}}):new Response('Not found',{status:404});
}};
async function sha(text){
 return hex(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text)));
}
function equal(a,b){
 if(a.length!==b.length)return false;
 let difference=0;
 for(let i=0;i<a.length;i++)difference|=a.charCodeAt(i)^b.charCodeAt(i);
 return difference===0;
}
function sessionCookie(request,role,value,age){
 const secure=new URL(request.url).protocol==='https:'?'; Secure':'';
 return 'xm_'+role+'='+value+'; HttpOnly'+secure+'; SameSite=Lax; Path=/; Max-Age='+age;
}
function tokenFrom(request,role){
 return (request.headers.get('cookie')||'').split(';').map(s=>s.trim()).find(s=>s.startsWith('xm_'+role+'='))?.split('=')[1]||'';
}
async function session(request,db,role){
 const token=tokenFrom(request,role);
 if(!/^[a-f0-9]{64}$/.test(token))return null;
 return db.prepare("SELECT s.user_id FROM auth_sessions s LEFT JOIN customers c ON c.id=s.user_id WHERE s.token=? AND s.role=? AND s.expires>? AND (s.role='admin' OR (c.verified=1 AND c.credential_version=s.credential_version))").bind(await sha(token),role,Date.now()).first();
}
async function createSession(request,db,role,userId,version=0){
 const token=hex(crypto.getRandomValues(new Uint8Array(32)));
 await db.prepare('DELETE FROM auth_sessions WHERE expires<=?').bind(Date.now()).run();
 await db.prepare('INSERT INTO auth_sessions(token,user_id,role,expires,credential_version) VALUES(?,?,?,?,?)').bind(await sha(token),userId,role,Date.now()+86400000,version).run();
 const otherRole=role==='admin'?'customer':'admin';
 await endSession(request,db,otherRole);
 const response=json({ok:true,role},200,{'set-cookie':sessionCookie(request,role,token,86400)});
 response.headers.append('set-cookie',sessionCookie(request,otherRole,'',0));
 return response;
}
async function endSession(request,db,role){
 await db.prepare('DELETE FROM auth_sessions WHERE token=? AND role=?').bind(await sha(tokenFrom(request,role)),role).run();
 return json({ok:true},200,{'set-cookie':sessionCookie(request,role,'',0)});
}
async function allowLogin(request,db,email){
 const bucket=Math.floor(Date.now()/900000);
 const ip=request.headers.get('x-nf-client-connection-ip')||'local';
 const keys=[await sha('ip:'+ip),await sha('email:'+String(email).toLowerCase().slice(0,254))];
 for(const [index,key] of keys.entries()){
  const row=await db.prepare('INSERT INTO auth_attempts(id,bucket,attempts) VALUES(?,?,1) ON CONFLICT(id) DO UPDATE SET attempts=CASE WHEN auth_attempts.bucket=? THEN auth_attempts.attempts+1 ELSE 1 END,bucket=? RETURNING attempts').bind(key,bucket,bucket,bucket).first();
  if(row.attempts>(index===0?60:12))return false;
 }
 return true;
}
function mailConfigured(env){
 try{
  const url=new URL(env.APP_URL);
  return (url.protocol==='https:'||(url.protocol==='http:'&&['localhost','127.0.0.1'].includes(url.hostname))) &&
   env.BREVO_API_KEY && !env.BREVO_API_KEY.startsWith('replace-') &&
   env.BREVO_SENDER_EMAIL && !env.BREVO_SENDER_EMAIL.startsWith('replace-');
 }catch{return false}
}
async function sendAccountEmail(env,customer,purpose){
 const token=hex(crypto.getRandomValues(new Uint8Array(32)));
 const tokenHash=await sha(token);
 await env.DB.prepare('INSERT INTO email_tokens(token,customer_id,purpose,expires) VALUES(?,?,?,?)')
  .bind(tokenHash,customer.id,purpose,Date.now()+1800000).run();
 const link=new URL('/account',env.APP_URL);
 link.hash=new URLSearchParams({action:purpose,token}).toString();
 const subject=purpose==='verify'?'Verify your Xarun Market account':'Reset your Xarun Market password';
 try{
  const response=await (env.mailFetch||fetch)('https://api.brevo.com/v3/smtp/email',{
   method:'POST',headers:{'api-key':env.BREVO_API_KEY,'Content-Type':'application/json'},
   body:JSON.stringify({
    sender:{email:env.BREVO_SENDER_EMAIL,name:env.BREVO_SENDER_NAME||'Xarun Market'},
    to:[{email:customer.email}],subject,
    textContent:subject+'\n\nOpen this link and choose your store password:\n'+link.href+
     '\n\nThis link expires in 30 minutes. If you did not request this email, you can ignore it.'
   }),
   signal:AbortSignal.timeout(10000)
  });
  if(!response.ok)throw Error('Email delivery failed');
 }catch(error){
  await env.DB.prepare('DELETE FROM email_tokens WHERE token=?').bind(tokenHash).run();
  throw error;
 }
}
async function finishEmailAction(request,env,input,purpose){
 if(!/^[a-f0-9]{64}$/.test(input.token||'')||typeof input.password!=='string'||input.password.length<12||input.password.length>128)return fail('Use a valid link and a password of 12–128 characters.');
 if(!await allowLogin(request,env.DB,'token:'+input.token.slice(0,16)))return fail('Too many attempts. Try again later.',429);
 const salt=crypto.randomUUID(),hash=await digest(input.password,salt),tokenHash=await sha(input.token);
 const changed=await env.DB.transaction(async db=>{
  const token=await db.prepare('DELETE FROM email_tokens WHERE token=? AND purpose=? AND expires>? RETURNING customer_id')
   .bind(tokenHash,purpose,Date.now()).first();
  if(!token)return false;
  const result=await db.prepare('UPDATE customers SET hash=?,salt=?,verified=1,credential_version=credential_version+1 WHERE id=?'+(purpose==='verify'?' AND verified=0':'')+' RETURNING id,email')
   .bind(hash,salt,token.customer_id).first();
  if(!result)return false;
  await db.prepare('DELETE FROM email_tokens WHERE customer_id=?').bind(result.id).run();
  await db.prepare('DELETE FROM auth_sessions WHERE user_id=? AND role=?').bind(result.id,'customer').run();
  await db.prepare('UPDATE orders SET user_id=? WHERE id IN (SELECT order_id FROM legacy_order_owners WHERE email=?)').bind(result.id,result.email).run();
  return true;
 });
 return changed?json({ok:true,message:'Password saved. You can now sign in.'}):fail('This link is invalid or expired. Request a new email.');
}
async function customerAuth(request,env,path,input){
 if(request.method!=='POST')return fail('Method not allowed',405);
 const db=env.DB;
 if(path==='/api/auth/logout'){
  const response=await endSession(request,db,'customer');
  const admin=await endSession(request,db,'admin');
  response.headers.append('set-cookie',admin.headers.get('set-cookie'));
  return response;
 }
 if(path==='/api/auth/verify')return finishEmailAction(request,env,input,'verify');
 if(path==='/api/auth/reset')return finishEmailAction(request,env,input,'reset');
 if(!['/api/auth/login','/api/auth/signup','/api/auth/resend','/api/auth/forgot'].includes(path))return fail('Not found',404);
 const email=String(input.email||'').trim().toLowerCase();
 if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)||email.length>254)return fail('Enter a valid email address.');
 if(!await allowLogin(request,db,email))return fail('Too many attempts. Try again in 15 minutes.',429);
 if(path!=='/api/auth/login'&&!mailConfigured(env))return fail('Email delivery is not configured. Contact the store owner.',503);
 if(path==='/api/auth/login'&&email===String(env.ADMIN_EMAIL||'').toLowerCase()){
  if(typeof env.ADMIN_PASSWORD!=='string'||env.ADMIN_PASSWORD.length<12||typeof input.password!=='string'||input.password.length<12||input.password.length>128)return fail('Incorrect email or password.',401);
  const expected=await sha(email+'|'+env.ADMIN_PASSWORD);
  if(!equal(await sha(email+'|'+input.password),expected))return fail('Incorrect email or password.',401);
  return createSession(request,db,'admin',expected);
 }
 let customer=await db.prepare('SELECT * FROM customers WHERE email=?').bind(email).first();
 if(path==='/api/auth/login'){
  if(typeof input.password!=='string'||input.password.length<12||input.password.length>128)return fail('Incorrect email or password.',401);
  const hash=await digest(input.password,customer?.salt||'invalid-account');
  if(!customer||!equal(hash,customer.hash))return fail('Incorrect email or password.',401);
  if(!customer.verified)return fail('Verify your email before signing in. Use Resend verification email.',403);
  return createSession(request,db,'customer',customer.id,customer.credential_version);
 }
 if(path==='/api/auth/signup'&&!customer){
  const salt=crypto.randomUUID(),hash=await digest(crypto.randomUUID(),salt);
  await db.prepare('INSERT INTO customers(id,email,hash,salt) VALUES(?,?,?,?) ON CONFLICT(email) DO NOTHING').bind(crypto.randomUUID(),email,hash,salt).run();
  customer=await db.prepare('SELECT * FROM customers WHERE email=?').bind(email).first();
 }
 const purpose=path==='/api/auth/forgot'?'reset':'verify';
 if(customer&&(purpose==='reset'||!customer.verified)){
  try{await sendAccountEmail(env,customer,purpose)}catch{return fail('Unable to send email right now. Please try again.',503)}
 }
 return json({ok:true,message:'If eligible, you will receive an email with the next step. Check your inbox and spam folder.'});
}
